/// The published version of each bake, read by the bake tools for their
/// output directory and by the client for the path it requests.
///
/// A published bake is immutable: re-baking bumps the version rather than
/// overwriting objects, which is what invalidates CDN edge and browser
/// caches. Bumping one here is the whole change.
///
/// All three moved together at v6/v6/v4, which is the one time they have:
/// that is the set baked before a page was named by its quadkey rather than
/// by a level and a decimal index (pxl-spec bake/quadkey.rs).
pub struct PublishedVersion {
    pub terrain: &'static str,
    pub poi: &'static str,
    pub geocode: &'static str,
}

pub const PUBLISHED_VERSION: PublishedVersion = PublishedVersion {
    terrain: "v7",
    poi: "v9",
    geocode: "v5",
};

/// The kinds a version is published for: the fields of `PUBLISHED_VERSION`,
/// numbered in their order.
#[allow(non_camel_case_types)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum BakeKind {
    terrain,
    poi,
    geocode,
}

impl BakeKind {
    pub const ALL: [BakeKind; 3] = [BakeKind::terrain, BakeKind::poi, BakeKind::geocode];

    /// The kind a number names, or none for a number nobody gave out.
    pub fn of(number: u32) -> Option<BakeKind> {
        BakeKind::ALL.into_iter().find(|k| *k as u32 == number)
    }
}

impl PublishedVersion {
    /// `PUBLISHED_VERSION[kind]`.
    pub fn of(&self, kind: BakeKind) -> &'static str {
        match kind {
            BakeKind::terrain => self.terrain,
            BakeKind::poi => self.poi,
            BakeKind::geocode => self.geocode,
        }
    }
}

/// What the published bake declares of itself to the client: `top_level`, the
/// coarsest level of the pyramid it supplies whole, terrain and POI alike. The
/// client's floor is held there, all around the eye, and the far edge is where
/// that level ends (pxl-kernel world/paging/floor.rs). The dev tile server
/// answers the same object at the tile root's `source`, with its `--top-level`
/// (pxl-geo-bake bin/serve_tiles.rs); neither is guessed from what fails.
pub const PUBLISHED_TOP_LEVEL: u32 = 10;

const _: () = assert!(PUBLISHED_TOP_LEVEL <= crate::space::pyramid::TOP_LEVEL, "a published level over the pyramid's top");
